INSERT INTO `news` (`id`, `title`, `category`, `date`, `status`, `cover`, `excerpt`, `body`, `region`, `author`, `seq`) VALUES ('mszr28e3k1m2','{\"uz\":\"Parlament diplomatiyasi va jadal ijtimoiy rivojlanishni qo‘llab-quvvatlash bo‘yicha xalqaro hamkorlik\",\"ru\":\"Парламентская дипломатия и международное сотрудничество в поддержку ускоренного социального развития\",\"en\":\"Parliamentary diplomacy and international cooperation in support of accelerated social development\"}','Diplomatiya','2026-08-18','published','uploads/parlament-diplomatiyasi-va-jadal-ijtimoi_20260819_090551_92807726.jpg','{\"uz\":\"Sessiyaga Jahon iqtisodiyoti va diplomatiya universitetining o‘quv ishlari bo‘yicha birinchi prorektori Akram Umarov moderatorlik qilmoqda.\",\"ru\":\"Модерирует сессию Акрам Умаров, первый проректор по учебной работе Университета мировой экономики и дипломатии.\",\"en\":\"The session is moderated by Akram Umarov, First Vice-Rector for Academic Affairs at the University of World Economy and Diplomacy.\"}','{\"uz\":\"Sessiya davomida<i>muhokama qilinmoqda</i>Barqaror rivojlanish maqsadlariga erishishda parlamentlararo hamkorlikning roli, parlamentlarning BMT tizimi institutlari va xalqaro tashkilotlar bilan o‘zaro hamkorligi, shuningdek, ijtimoiy tashabbuslarni amalga oshirish va aholi turmush sifatini oshirishda xalqaro hamkorlik istiqbollari masalalari.<br><br>Munozarada<i>ishtirok eting</i> <b>Qahramon Allaberganov</b>, Markaziy Osiyo xalqaro instituti kafedra mudiri,<b>Shaxlo Hamraxo\'jaeva</b>, O‘zbekiston Respublikasi Prezidenti huzuridagi Strategik va mintaqalararo tadqiqotlar instituti yetakchi ilmiy xodimi va<b>Ulug\'bek Xasanov</b>, Jahon iqtisodiyoti va diplomatiya universitetining xalqaro aloqalar kafedrasi professori, “Politics, Law, Economics” xalqaro jurnali bosh muharriri.\",\"ru\":\"В ходе сессии <i>обсуждаются</i> вопросы роли межпарламентского сотрудничества в достижении Целей устойчивого развития, взаимодействия парламентов с учреждениями системы ООН и международными организациями, а также перспективы международного сотрудничества в реализации социальных инициатив и повышении качества жизни населения.<br><br>В обсуждении <i>принимают участие</i> <b>Кахрамон Аллаберганов</b>, начальник отдела Международного института Центральной Азии, <b>Шахло Хамрахожаева</b>, ведущий научный сотрудник Института стратегических и межрегиональных исследований при Президенте Республики Узбекистан, и <b>Улугбек Хасанов</b>, профессор кафедры международных отношений Университета мировой экономики и дипломатии, главный редактор международного журнала «Политика, право, экономика».\",\"en\":\"During the session<i>are being discussed</i>issues of the role of inter-parliamentary cooperation in achieving the Sustainable Development Goals, interaction of parliaments with institutions of the UN system and international organizations, as well as prospects for international cooperation in the implementation of social initiatives and improving the quality of life of the population.<br><br>In discussion<i>take part</i> <b>Kakhramon Allaberganov</b>, Head of Department, International Institute of Central Asia,<b>Shakhlo Hamrakhozhaeva</b>, leading researcher at the Institute for Strategic and Interregional Studies under the President of the Republic of Uzbekistan, and<b>Ulugbek Khasanov</b>, Professor of the Department of International Relations at the University of World Economy and Diplomacy, editor-in-chief of the international journal “Politics, Law, Economics”.\"}','Markaziy Osiyo','Daria Gorelkina',38);
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
