INSERT INTO `pages` (`id`, `title`, `slug`, `body`, `status`, `seq`) VALUES ('14elbtemsgcdafq3eyb','{\"uz\":\"Tashqi siyosiy tadqiqotlar va xalqaro tashabbuslar markazi\",\"ru\":\"\",\"en\":\"\"}','biz-kimmiz','{\"uz\":\"<p><b>Tashqi siyosiy tadqiqotlar va xalqaro tashabbuslar markazi (TSTM) O‘zbekiston Respublikasi tashqi siyosati, xalqaro siyosiy va iqtisodiy munosabatlarning dolzarb masalalari bo‘yicha kompleks ilmiy-tadqiqot va tahliliy faoliyatni amalga oshiruvchi davlat ilmiy-tadqiqot va tahliliy markazi hisoblanadi.</b></p><p><b>Markaz O‘zbekiston Respublikasi Tashqi ishlar vazirligining asosiy tahliliy va ekspertlik tuzilmalaridan biri sifatida tashqi siyosatning siyosiy, xalqaro, iqtisodiy va strategik yo‘nalishlarida tadqiqotlar olib boradi. Markaz tomonidan tayyorlanadigan tahliliy va ekspertlik materiallari mamlakat tashqi siyosatining ustuvor yo‘nalishlarini belgilash, strategik vazifalarini shakllantirish hamda ularni amalga oshirish jarayonlarini ilmiy-tahliliy jihatdan qo‘llab-quvvatlashga xizmat qiladi.</b></p><p><b>TSTM faoliyatining ustuvor yo‘nalishlaridan biri O‘zbekiston Respublikasining asosiy tashqi siyosiy hamkorlari bilan ikki tomonlama munosabatlar va amaliy hamkorlikning holati hamda istiqbollarini o‘rganishdan iborat. Shu bilan birga, Markaz global va mintaqaviy miqyosda yuz berayotgan muhim siyosiy, iqtisodiy va geosiyosiy jarayonlarni muntazam ravishda tahlil qiladi hamda ularning O‘zbekiston Respublikasi tashqi siyosati va milliy manfaatlariga ehtimoliy ta’sirini o‘rganadi.</b></p><p><b>Markaz xalqaro va mintaqaviy masalalar bo‘yicha ekspertlik muloqotini rivojlantirish, ilmiy-amaliy konferensiyalar, davra suhbatlari, seminarlar va boshqa xalqaro ekspertlik tadbirlarini tashkil etish hamda o‘tkazishda faol ishtirok etadi.</b></p><p><b>TSTM xalqaro munosabatlar, mintaqaviy jarayonlar va xavfsizlikning dolzarb masalalarini tadqiq etishga ixtisoslashgan xorijiy tahliliy va ilmiy-tadqiqot markazlari bilan muntazam ekspertlik muloqotlarini yo‘lga qo‘yish, ilmiy-tadqiqot va tahliliy loyihalarni birgalikda amalga oshirish, o‘zaro tajriba almashish hamda xalqaro munosabatlarning dolzarb masalalari yuzasidan qo‘shma ekspertlik tashabbuslarini ilgari surish uchun ochiq va tayyor.</b></p>\",\"ru\":\"\",\"en\":\"\"}','published',13);
